version, _ := obj["version"].(string)
sch := schemaFor(version)
if sch == nil {
	return nil, fmt.Errorf("%s says its version is %q, and this build reads %s and %s. A reader that does not know a version refuses the file rather than guessing which half of it it still understands",
		name, version, FormatV1, FormatV2)
}
res.Errors = sch.Validate(generic)

case FormatV2:
	d := &Doc2{}
	if err := json.Unmarshal(lifted, d); err != nil {
		return nil, fmt.Errorf("%s does not match the schema: %w", name, err)
	}
	res.Doc2 = d
	inspect2(res, d)
	res.checkSchemaURL(d.Schema, FormatV2)

root := resolveRoot(f, res.View().RootHint)

sub, err := fs.Sub(webFS, "web")
if err != nil {
	die("the web assets are missing from this build: %v", err)
}
key := commentKey(f.slug, abs)
s := &server{file: abs, root: root, dev: f.dev, token: randomToken(),
	vendor: NewVendor(settings.Offline), web: sub,
	key: key, title: res.View().Title, comments: openComments(key, res.View().Title)}

step(step, host) {
  for (const [i, b] of (step.blocks || []).entries()) {
    const node = blockNode(b, i);
    if (!node) continue;
    // The spacing belongs to being a block rather than to being a diagram or a
    // diff, so it is set here and the builders only say what they are.
    node.classList.add("block");
    if (b.id) node.dataset.block = b.id;

view := res.View()
return &payload{
	Doc: d, Hosted: true, Meta: m, GitHub: BuildGitHubLinks(view.Source),
	Settings: defaultSettings(),
	Stamp:    stamp,
}, nil

const start = result.startLine! - 1, end = result.endLine! - 1;
const editor = reveal ? await vscode.window.showTextDocument(document, { preview: true, preserveFocus: true, viewColumn: vscode.ViewColumn.One })
  : vscode.window.visibleTextEditors.find(e => e.document.uri.toString() === document.uri.toString());
if (!editor) return;
this.decorate(editor, block, start, end);
if (reveal) {
  const first = relativeLine ?? block.snippet.highlights?.[0]?.lines.start ?? 1;
  editor.selection = new vscode.Selection(start + first - 1, 0, start + first - 1, 0);
  editor.revealRange(new vscode.Range(start, 0, end, document.lineAt(end).text.length), vscode.TextEditorRevealType.InCenterIfOutsideViewport);

var commentsDir = func() (string, error) {
	p, err := settingsPath()
	if err != nil {
		return "", err
	}
	return filepath.Join(filepath.Dir(p), "comments"), nil

func SkillDoc(base string) string {
	parts := []string{
		fill(agentIntroMD, base),
		rulesMD,
		dataMD,
		fill(agentAPIMD, base),
	}
	return strings.Join(parts, "\n\n---\n\n")
